def transform(grid):
    """Draw full cross-lines from paired edge markers; recolor touched 2-components."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    horizontal = {r for r in range(h) if grid[r][0] == 1 and grid[r][w-1] == 1}
