from collections import deque

def transform(grid):
    w = max(map(len, grid))
    grid = [row[:] + [0] * (w - len(row)) for row in grid]
    h = len(grid)
    out = [row[:] for row in grid]
    horizontal = {r for r in range(h) if grid[r][0] == 1 and grid[r][w-1] == 1}
    vertical = {c for c in range(w) if grid[0][c] == 1 and grid[h-1][c] == 1}
    lines = {(r,c) for r in horizontal for c in range(w)} | {(r,c) for c in vertical for r in range(h)}
    # Recolor every 4-connected 2-object hit by a marker line.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            comp = []
            hit = False
            while q:
                y,x = q.popleft()
                comp.append((y,x))
                hit |= (y,x) in lines
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if hit:
                for y,x in comp: out[y][x] = 1
    for r,c in lines: out[r][c] = 1
    return out
